mapper.sql:
WHERE i.tenant_id=#{tenantId}

    AND i.status='PENDING' AND i.expires_time > #{now}
    AND (i.status='EXPIRED' OR (i.status='PENDING' AND i.expires_time <= #{now}))
    AND i.status=#{status}

mapper.select:
SELECT  
WHERE m.tenant_id=#{tenantId} AND m.member_id=#{memberId}
FOR UPDATE OF m

SELECT  
WHERE m.tenant_id=#{tenantId} AND m.account_id=#{accountId}
FOR UPDATE OF m

mapper.update:
UPDATE t_tenant_member SET status='ACTIVE', member_type=#{memberType}, invited_by=#{invitedBy},
    version=version+1, update_time=#{now}
WHERE member_id=#{memberId} AND version=#{version} AND status='REVOKED' AND member_type<>'OWNER'

UPDATE t_tenant_invitation SET status='ACCEPTED', active_slot=NULL, accepted_account_id=#{accountId},
    accepted_member_id=#{memberId}, accepted_time=#{now}, version=version+1, update_time=#{now}
WHERE invitation_id=#{invitationId} AND version=#{version} AND status='PENDING' AND expires_time > #{now}

UPDATE t_authentication_challenge SET status='SUPERSEDED', active_slot=NULL, version=version+1, update_time=#{now}
WHERE challenge_id=#{challengeId} AND  AND status='PENDING' AND active_slot=1
    AND version=#{version}

UPDATE t_authentication_challenge SET status='REVOKED', active_slot=NULL, version=version+1, update_time=#{now}
WHERE challenge_id=#{challengeId} AND  AND status='PENDING' AND active_slot=1
    AND version=#{version}

UPDATE t_authentication_challenge SET status='CONSUMED', active_slot=NULL, consumed_time=#{now},
    version=version+1, update_time=#{now}
WHERE challenge_id=#{challengeId} AND  AND version=#{version}
    AND status='PENDING' AND active_slot=1 AND expires_time>#{now} AND max_attempts=5
    AND used_attempts<max_attempts
